function icon(name,label=''){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="${label?'false':'true'}"${label?` aria-label="${esc(label)}"`:''}>${ICONS[name]||ICONS.music}</svg>`}
